fn at(index:i64)->DateTime<Utc>{DateTime::from_timestamp(1_700_000_000+index*60,0).unwrap()}
fn bar(index:i64,close:D,volume:Option<D>)->QuantBar{QuantBar{open_time:at(index),bucket_end:at(index+1),open:close.clone(),high:&close+D::one(),low:&close-D::one(),close,known_volume_sum:volume.clone().unwrap_or_default(),known_volume_count:u64::from(volume.is_some()),component_count:1,volume,state:"final".into(),revision:1,observed_at:at(index+1),received_at:at(index+1),accepted_at:Some(at(index+1)),finalized_at:Some(at(index+1)),applied_frame_seq:Some(index as u64+1),source_precision_ns:Some(1),source_volume_components:None,source_volume_component_groups:Vec::new()}}
#[test]
fn structural_coverage_is_hashed_and_displayed_without_a_market_clock() {
    let mut parameters = Parameters::default();
    parameters.enabled_strategies.insert("vix-gvz".into());
    let mut source = input(vec![bar(0,d("100"),None)],at(5));
    let baseline = evidence(&source,&parameters).unwrap();
    for kind in ["calendar_coverage", "source_point_coverage", "source_clock_coverage", "volatility"] {
        source.external_facts.push(ExternalFact { kind:kind.into(), source:"same-view-fixture".into(), record_id:Some(kind.into()), revision:Some(1), provenance:json!({"snapshot_version":{"commit_id":"1"}}), observed_at:None, published_at:None, received_at:None, unavailable_reason:None, value:json!({"source_event_coverage_complete":false,"known_unclassified_point_count_lower_bound":"2","sha256":"fixed-point-summary"}) });
    }
    let before = evidence(&source,&parameters).unwrap();
    assert_ne!(baseline.input_hash,before.input_hash);
    assert_ne!(baseline.effective_input_hash,before.effective_input_hash);
    let pure = super::snapshot::evaluate(&source,&parameters).unwrap();
    assert!(pure.confirmed.as_ref().unwrap().indicators["volatility"].is_null(), "coverage never supplies a market observation");
    for fact in &pure.external[..3] {
        assert_eq!(fact["included"],true);
        assert!(fact["known_at"].is_null() && fact["received_at"].is_null());
        assert!(fact["unavailable_reason"].is_null());
        assert_eq!(fact["value"]["known_unclassified_point_count_lower_bound"],"2");
        assert!(fact["evidence_role"].as_str().unwrap().contains("structural_coverage"));
    }
    assert_eq!(pure.external[3]["included"],false);
    assert_eq!(pure.external[3]["unavailable_reason"],"unknown availability time");
    let mut accumulator = super::snapshot::SnapshotAccumulator::new(parameters.clone()).unwrap();
    accumulator.push(source.clone()).unwrap();
    let current = accumulator.current().unwrap();
    assert_eq!(pure.external,current.external);
    assert_eq!(pure.evidence.input_hash,current.evidence.input_hash);
    source.decision_as_of=at(6); source.token.commit_id+=1;
    source.external_facts[1].provenance["snapshot_version"]["commit_id"]=json!("2");
    let clock_only=evidence(&source,&parameters).unwrap();
    assert_eq!(before.effective_input_hash,clock_only.effective_input_hash);
    source.external_facts[1].value["known_unclassified_point_count_lower_bound"]=json!("3");
    let changed=evidence(&source,&parameters).unwrap();
    assert_ne!(clock_only.input_hash,changed.input_hash);
    assert_ne!(clock_only.effective_input_hash,changed.effective_input_hash);
    let mut resumed=super::snapshot::SnapshotAccumulator::restore(accumulator.snapshot().unwrap(),&parameters).unwrap().resume();
    let mut context=source.clone(); context.bars.clear(); resumed.push(context).unwrap();
    assert_eq!(resumed.current().unwrap().evidence.input_hash,changed.input_hash);
}
#[test]fn effective_ai_identity_changes_only_for_visible_inputs_not_read_clocks(){
 let p=Parameters::default();let mut source=input((0..30).map(|i|bar(i,d("100"),None)).collect(),at(31));source.quote=Some(QuantQuote{price:d("100"),observed_at:at(30),received_at:at(30),accepted_at:Some(at(30)),applied_frame_seq:Some(30),source_precision_ns:Some(1)});source.external_facts.push(ExternalFact{record_id:Some("derived-commit-1".into()),revision:Some(1),provenance:json!({"snapshot_version":{"commit_id":"1"},"aggregation_version":"fixed"}),kind:"multi_timeframe".into(),source:"fixture".into(),observed_at:Some(at(29)),published_at:None,received_at:Some(at(30)),unavailable_reason:None,value:json!({"horizons":[],"decision_cutoff_ns":"read-clock-1"})});
 let first=evidence(&source,&p).unwrap();source.decision_as_of=at(32);source.token.commit_id+=1;source.external_facts[0].record_id=Some("derived-commit-2".into());source.external_facts[0].revision=Some(2);source.external_facts[0].provenance["snapshot_version"]["commit_id"]=json!("2");source.external_facts[0].value["decision_cutoff_ns"]=json!("read-clock-2");let same=evidence(&source,&p).unwrap();assert_eq!(first.effective_input_hash,same.effective_input_hash);assert_ne!(first.input_hash,same.input_hash);
 source.external_facts.push(ExternalFact{record_id:Some("future-publication".into()),revision:Some(1),provenance:json!({"source":"fixed"}),kind:"volatility".into(),source:"fixed-external".into(),observed_at:Some(at(1)),published_at:None,received_at:Some(at(33)),unavailable_reason:None,value:json!({"vix":"20"})});assert_eq!(same.effective_input_hash,evidence(&source,&p).unwrap().effective_input_hash);source.decision_as_of=at(33);let visible=evidence(&source,&p).unwrap();assert_ne!(same.effective_input_hash,visible.effective_input_hash);
 let mut event=source.clone();event.quote.as_mut().unwrap().received_at=at(31);event.quote.as_mut().unwrap().applied_frame_seq=Some(31);assert_ne!(visible.effective_input_hash,evidence(&event,&p).unwrap().effective_input_hash,"same price is a new genuine event when source receipt/sequence differs");let mut params=p.clone();params.rsi_period=10;assert_ne!(visible.effective_input_hash,evidence(&source,&params).unwrap().effective_input_hash);
 let mut forming=bar(30,d("101"),None);forming.state="forming".into();forming.finalized_at=None;source.bars.push(forming);let preview=evidence(&source,&p).unwrap();source.bars[30]=bar(30,d("101"),None);assert_ne!(preview.effective_input_hash,evidence(&source,&p).unwrap().effective_input_hash,"forming becomes confirmed");
}
#[test]fn unchanged_recursive_prefix_does_not_require_checkpoint_republication(){
 let parameters=Parameters::default();let mut accumulator=super::snapshot::SnapshotAccumulator::new(parameters.clone()).unwrap();let initial=input((0..30).map(|i|bar(i,d("100"),None)).collect(),at(31));accumulator.push(initial).unwrap();let identity=accumulator.checkpoint_identity().unwrap();let saved=accumulator.snapshot().unwrap();let mut resumed=super::snapshot::SnapshotAccumulator::restore(saved,&parameters).unwrap().resume();let mut context=input(vec![],at(32));context.token.commit_id+=1;context.token.committed_frame_seq+=1;context.quote=Some(QuantQuote{price:d("123"),observed_at:at(31),received_at:at(31),accepted_at:Some(at(31)),applied_frame_seq:Some(31),source_precision_ns:Some(1)});resumed.push(context).unwrap();assert_eq!(identity,resumed.checkpoint_identity().unwrap());let current=resumed.current().unwrap();assert_eq!(current.quote.unwrap().price,d("123"));assert_eq!(current.evidence.token.commit_id,10001);let mut append=resumed.resume();append.push(input(vec![bar(30,d("101"),None)],at(32))).unwrap();assert_ne!(identity,append.checkpoint_identity().unwrap());
}
