#[test]fn tiny_variance_uses_guard_precision_and_exact_cancellation(){let tiny=d("0.00000000000000000001");let values=[-tiny.clone(),tiny.clone()];let sum=values.iter().cloned().sum::<D>();let squares=values.iter().map(|v|v*v).sum::<D>();assert_eq!(super::exact::population_deviation(&sum,&squares,2),Some(tiny.clone()));let shift=d("10000000000000000.01");let shifted=[&shift-&tiny,&shift+&tiny];assert_eq!(super::exact::population_deviation(&shifted.iter().cloned().sum::<D>(),&shifted.iter().map(|v|v*v).sum::<D>(),2),Some(tiny));}
