#[test]fn state_only_warmup_matches_complete_prefix_points_series_and_restore(){let mut p=Parameters::default();p.enabled_strategies=strategy_catalog().iter().map(|s|s.id.into()).collect();let mut oracle=Evaluator::new(p.clone()).unwrap();let mut fast=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();let mut all_series=std::collections::VecDeque::new();let mut buffer=vec![];for index in 0..5200{let b=bar(index,d("100")+D::from(index%13)+super::exact::div(&D::from(index%31),&d("10")),if index%17==0{None}else{Some(D::from(index%1000))});let mut point=oracle.push(b.clone(),&HistorySemantics::FinalRevisionHistory).unwrap();all_series.push_back(super::snapshot::ChartIndicatorPoint::from(&point));if all_series.len()>1024{all_series.pop_front();}buffer.push(b);if buffer.len()==127||index==5199{let batch=input(std::mem::take(&mut buffer),at(5200));super::snapshot::external_context_at(&mut point,&batch,batch.decision_as_of);fast.push(batch).unwrap();let current=fast.current().unwrap();assert_eq!(serde_json::to_value(&current.confirmed).unwrap(),serde_json::to_value(Some(point)).unwrap(),"batch ending {index}");assert_eq!(current.series.len(),all_series.len());for (position,(actual,expected))in current.series.iter().zip(&all_series).enumerate(){assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(expected).unwrap(),"series ending {index} point {position}");}if index>3500&&index<3750{fast=super::snapshot::SnapshotAccumulator::restore(fast.snapshot().unwrap(),&p).unwrap();}}}assert!(fast.current().unwrap().bars.len()<5200-2*1200,"oracle must cross at least two actual bounded drains");}
#[test]fn execution_context_skip_preserves_every_eligible_decision(){let mut p=Parameters::default();p.enabled_strategies=strategy_catalog().iter().map(|s|s.id.into()).collect();let mut full=Evaluator::new(p.clone()).unwrap();let mut trading=Evaluator::new(p).unwrap();for index in 0..350{let b=bar(index,d("100")+D::from(index%13),Some(D::from(index%1000)));let a=full.push(b.clone(),&HistorySemantics::FinalRevisionHistory).unwrap();let b=trading.push_execution(b,&HistorySemantics::FinalRevisionHistory).unwrap();assert_eq!(a.composite_score,b.composite_score);assert_eq!(a.direction,b.direction);let a:Vec<_>=a.signals.iter().filter(|s|s.backtest_eligible).collect();let b:Vec<_>=b.signals.iter().filter(|s|s.backtest_eligible).collect();assert_eq!(serde_json::to_value(a).unwrap(),serde_json::to_value(b).unwrap());}}
#[test]#[ignore="explicit cold state-only performance benchmark"]fn state_only_long_stream_profile(){
 let count=std::env::var("TRACEFANG_QUANT_BENCH_BARS").ok().and_then(|v|v.parse::<i64>().ok()).unwrap_or(10_000);let mut p=Parameters::default();p.enabled_strategies=strategy_catalog().iter().map(|s|s.id.into()).collect();let mut acc=super::snapshot::SnapshotAccumulator::new(p).unwrap();let start=std::time::Instant::now();let mut batch=vec![];
 for index in 0..count{batch.push(bar(index,d("100")+D::from(index%13)+super::exact::div(&D::from(index%31),&d("10")),if index%17==0{None}else{Some(D::from(index%1000))}));if batch.len()==256||index+1==count{acc.push(input(std::mem::take(&mut batch),at(count))).unwrap();}if index%50_000==0{eprintln!("typed progress {index}/{count} elapsed {}ms",start.elapsed().as_millis());}}
 let warmup=start.elapsed().as_millis();let materialize=std::time::Instant::now();let current=acc.current().unwrap();let materialize_ms=materialize.elapsed().as_millis();let repeat=std::time::Instant::now();let repeated=acc.current().unwrap();let repeat_us=repeat.elapsed().as_micros();assert_eq!(current.evidence.snapshot_hash,repeated.evidence.snapshot_hash);let append=std::time::Instant::now();let mut resumed=acc.clone().resume();resumed.push(input(vec![bar(count,d("101"),None)],at(count+1))).unwrap();let appended=resumed.current().unwrap();let append_us=append.elapsed().as_micros();assert_eq!(appended.evidence.confirmed_count,count as usize+1);
 println!("{}",json!({"bars":count,"fixture_watermark":10000.max(count as u64).to_string(),"warmup_ms":warmup,"materialize_ms":materialize_ms,"cold_total_ms":warmup+materialize_ms,"repeat_current_microseconds":repeat_us,"append_with_point_and_series_microseconds":append_us,"confirmed_count":current.evidence.confirmed_count,"snapshot_hash":current.evidence.snapshot_hash,"checkpoint_bytes":serde_json::to_vec(&acc.snapshot().unwrap()).unwrap().len(),"display_points":current.series.len(),"retained_bars":current.bars.len(),"mode":"all17 enabled; every history bar typed recurrence; complete endpoint and last1024 materialize; appended and repeated render cache"}));
}

#[test]fn snapshot_external_clock_does_not_rewrite_historical_decision(){let mut p=Parameters::default();p.enabled_strategies.insert("vix-gvz".into());let mut i=input(vec![bar(0,d("100"),None)],at(5));i.external_facts.push(ExternalFact{record_id:Some("fixed-test-record".into()),revision:Some(1),provenance:json!({"fixture":true}),kind:"volatility".into(),source:"fixed-evidence".into(),observed_at:Some(at(0)),published_at:None,received_at:Some(at(3)),unavailable_reason:None,value:json!({"value":"1"})});let snapshot=super::snapshot::evaluate(&i,&p).unwrap();let current=snapshot.confirmed.unwrap();assert_eq!(current.indicators["volatility"]["value"],"1");assert_eq!(current.decision_at,at(1));assert_eq!(current.indicators["external_context_cutoff"],json!(at(5)));let mut historical=Evaluator::new(p.clone()).unwrap().push(i.bars[0].clone(),&i.semantics).unwrap();super::snapshot::external_context(&mut historical,&i);assert!(historical.indicators["volatility"].is_null());let mut replay=i.clone();replay.semantics=HistorySemantics::OriginalEventReplay;replay.application_cursor=Some(1);replay.decision_as_of=at(1);assert!(super::snapshot::evaluate(&replay,&p).unwrap().confirmed.unwrap().indicators["volatility"].is_null());}

#[test]fn maximum_ma_window_typed_warmup_drains_and_restores(){
 let mut p=Parameters::default();p.ma_periods=vec![30,120,512,4096];p.enabled_strategies=BTreeSet::from(["macd".into(),"ma-structure".into(),"bollinger".into(),"rsi".into()]);
 let mut oracle=Evaluator::new(p.clone()).unwrap();oracle.retain_all_for_oracle();let mut fast=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();let mut pending=vec![];let mut chart_oracle=std::collections::VecDeque::new();let count=21_000;
 for index in 0..count{let b=bar(index,d("100")+D::from(index%13),Some(D::from(index%1000)));let mut expected=oracle.push(b.clone(),&HistorySemantics::FinalRevisionHistory).unwrap();chart_oracle.push_back(super::snapshot::ChartIndicatorPoint::from(&expected));if chart_oracle.len()>1024{chart_oracle.pop_front();}pending.push(b);
  if pending.len()==256||index+1==count{let batch=input(std::mem::take(&mut pending),at(count));super::snapshot::external_context_at(&mut expected,&batch,batch.decision_as_of);fast.push(batch).unwrap();if index==12543{fast=super::snapshot::SnapshotAccumulator::restore(fast.snapshot().unwrap(),&p).unwrap();}if index+1==count{let actual=fast.current().unwrap();assert!(actual.bars.len()<11000,"must cross at least two actual drains");assert_eq!(serde_json::to_value(&actual.series).unwrap(),serde_json::to_value(&chart_oracle).unwrap());assert_eq!(serde_json::to_value(actual.confirmed).unwrap(),serde_json::to_value(Some(expected)).unwrap());}}
 }
}
#[test]fn typed_render_cache_append_and_external_refresh_match_cold(){
 let p=Parameters::default();let rows:Vec<_>=(0..1450).map(|i|bar(i,d("100")+D::from(i%13),None)).collect();let mut acc=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();acc.push(input(rows[..1449].to_vec(),at(1450))).unwrap();let first=acc.current().unwrap();assert_eq!(first.series.len(),1024);let repeated=acc.current().unwrap();assert_eq!(serde_json::to_value(first).unwrap(),serde_json::to_value(repeated).unwrap());let mut resumed=acc.resume();resumed.push(input(rows[1449..].to_vec(),at(1450))).unwrap();let warm=resumed.current().unwrap();let mut cold=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();cold.push(input(rows,at(1450))).unwrap();let expected=cold.current().unwrap();assert_eq!(serde_json::to_value(warm).unwrap(),serde_json::to_value(expected).unwrap());
}

#[test]fn resumed_prefix_preview_counts_match_current_canonical_input(){
 let p=Parameters::default();let mut rows:Vec<_>=(0..8).map(|i|bar(i,d("100"),None)).collect();rows[2].state="forming".into();rows[2].finalized_at=None;rows[7].state="forming".into();rows[7].finalized_at=None;
 let mut acc=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();acc.push(input(rows.clone(),at(8))).unwrap();let before=acc.current().unwrap();assert_eq!(before.evidence.preview_count,2);let mut resumed=acc.resume();resumed.push(input(rows[7..].to_vec(),at(8))).unwrap();let hot=resumed.current().unwrap();assert_eq!(hot.evidence.input_count,before.evidence.input_count);assert_eq!(hot.evidence.preview_count,before.evidence.preview_count);assert_eq!(hot.evidence.input_hash,before.evidence.input_hash);
 rows[7].state="final".into();rows[7].finalized_at=Some(at(8));let mut hot_acc=resumed.resume();hot_acc.push(input(rows[7..].to_vec(),at(8))).unwrap();let hot=hot_acc.current().unwrap();let mut cold=super::snapshot::SnapshotAccumulator::new(p).unwrap();cold.push(input(rows,at(8))).unwrap();let cold=cold.current().unwrap();assert_eq!(hot.evidence.input_count,cold.evidence.input_count);assert_eq!(hot.evidence.preview_count,cold.evidence.preview_count);assert_eq!(hot.evidence.confirmed_count,cold.evidence.confirmed_count);assert_eq!(hot.evidence.input_hash,cold.evidence.input_hash);
}

#[test]fn nullable_canonical_volume_keeps_distinct_source_component_evidence(){
 let mut value=bar(1,d("100"),None);value.source_volume_components=Some(SourceVolumeComponents{known_volume_sum:d("2.0000000000000000000000000001"),known_count:1,total_count:2,policy:"fuyao-source-field-13-interval-v1".into()});value.validate().unwrap();
 assert!(value.volume.is_none());assert_eq!(value.known_volume_sum,d("0"));assert_eq!((value.known_volume_count,value.component_count),(0,1));
 let encoded=serde_json::to_value(&value).unwrap();assert_eq!(encoded["source_volume_components"]["known_volume_sum"],"2.0000000000000000000000000001");assert_eq!(encoded["source_volume_components"]["known_count"],"1");assert_eq!(encoded["source_volume_components"]["total_count"],"2");
 let original=content_hash(&value).unwrap();value.source_volume_components.as_mut().unwrap().known_volume_sum=d("3");assert_ne!(content_hash(&value).unwrap(),original);
 for (sum,known,total) in [("-1",1,2),("1",3,2),("1",0,2)]{value.source_volume_components=Some(SourceVolumeComponents{known_volume_sum:d(sum),known_count:known,total_count:total,policy:"fixed-source-policy".into()});assert!(value.validate().is_err());}
 value.source_volume_components=None;assert!(serde_json::to_value(value).unwrap().get("source_volume_components").is_none());
}

#[test]fn distinct_source_volume_policies_remain_separate_and_bounded(){
 let mut value=bar(1,d("100"),None);let original=serde_json::to_value(&value).unwrap();
 assert!(original.get("source_volume_component_groups").is_none());let old:QuantBar=serde_json::from_value(original).unwrap();assert!(old.source_volume_component_groups.is_empty());assert_eq!(content_hash(&value).unwrap(),content_hash(&old).unwrap());
 let source=SourceVolumeComponents{known_volume_sum:d("2.0000000000000000000000000001"),known_count:1,total_count:2,policy:"fuyao-source-field-13-interval-v1".into()};
 let fallback=SourceVolumeComponents{known_volume_sum:d("7"),known_count:1,total_count:1,policy:"canonical-minute-fallback-v1".into()};
 value.source_volume_component_groups=vec![source.clone(),fallback];value.validate().unwrap();assert!(value.volume.is_none());assert!(value.known_volume_sum.is_zero());
 let encoded=serde_json::to_value(&value).unwrap();assert!(encoded.get("source_volume_components").is_none());assert_eq!(encoded["source_volume_component_groups"][1]["known_volume_sum"],"2.0000000000000000000000000001");assert_eq!(encoded["source_volume_component_groups"][0]["known_volume_sum"],"7");let restored:QuantBar=serde_json::from_value(encoded).unwrap();assert_eq!(restored.source_volume_component_groups[0].policy,"canonical-minute-fallback-v1");assert_eq!(content_hash(&value).unwrap(),content_hash(&restored).unwrap());let mut reversed=value.clone();reversed.source_volume_component_groups.reverse();assert_eq!(content_hash(&value).unwrap(),content_hash(&reversed).unwrap());
 let hash=content_hash(&value).unwrap();value.source_volume_component_groups[1].known_volume_sum=d("8");assert_ne!(hash,content_hash(&value).unwrap());
 value.source_volume_components=Some(source.clone());assert!(value.validate().is_err());value.source_volume_components=None;
 value.source_volume_component_groups=vec![source.clone(),source.clone()];assert!(value.validate().is_err());
 value.source_volume_component_groups=(0..9).map(|i|SourceVolumeComponents{policy:format!("policy-{i}"),..source.clone()}).collect();assert!(value.validate().is_err());
 value.source_volume_component_groups.truncate(8);value.validate().unwrap();value.source_volume_component_groups[0].known_count=0;assert!(value.validate().is_err());value.source_volume_component_groups=vec![SourceVolumeComponents{known_volume_sum:d("0"),known_count:0,total_count:0,policy:"empty-policy".into()}];assert!(value.validate().is_err());
}

#[test]fn source_group_order_preserves_cold_snapshot_and_resumed_prefix_hash(){
 let source=SourceVolumeComponents{known_volume_sum:d("2.0000000000000000000000000001"),known_count:1,total_count:2,policy:"fuyao-source-field-13-interval-v1".into()};
 let fallback=SourceVolumeComponents{known_volume_sum:d("0"),known_count:0,total_count:1,policy:"canonical-minute-fallback-v1".into()};
 let mut a=bar(0,d("100"),None);a.source_volume_component_groups=vec![source.clone(),fallback.clone()];
 let mut b=bar(1,d("101"),None);b.source_volume_component_groups=vec![source,fallback];
 let p=Parameters::default();let full=input(vec![a.clone(),b.clone()],at(2));let mut full_acc=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();full_acc.push(full).unwrap();let cold=full_acc.current().unwrap();
 a.source_volume_component_groups.reverse();b.source_volume_component_groups.reverse();let mut reversed_acc=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();reversed_acc.push(input(vec![a.clone(),b.clone()],at(2))).unwrap();let reversed=reversed_acc.current().unwrap();assert_eq!(serde_json::to_value(&cold).unwrap(),serde_json::to_value(reversed).unwrap());
 let mut acc=super::snapshot::SnapshotAccumulator::new(p.clone()).unwrap();acc.push(input(vec![a],at(2))).unwrap();let mut restored=super::snapshot::SnapshotAccumulator::restore(acc.snapshot().unwrap(),&p).unwrap().resume();restored.push(input(vec![b],at(2))).unwrap();assert_eq!(serde_json::to_value(cold).unwrap(),serde_json::to_value(restored.current().unwrap()).unwrap());
}
